"""Named response contracts read from the a355 handlers; documentation only."""
def s(description, **extra):return dict(type='string',description=description,**extra)
def n(description, **extra):return dict(type='integer',description=description,**extra)
def b(description):return dict(type='boolean',description=description)
def ref(name, description=None):
    value={'$ref':'#/components/schemas/'+name}
    if description:value['description']=description
    return value
def arr(items,description):return dict(type='array',items=items,description=description)
def obj(fields,description,required=None):return dict(type='object',description=description,properties=fields,required=list(fields)if required is None else required)
def nullable(value):
    result={'anyOf':[value,{'type':'null'}]}
    if value.get('description'):result['description']=value['description']
    return result
